#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-29
#
# Test: every skill that mentions SendMessage states the two CC 2.1.248
# cross-session delivery facts (#3772, #3773):
#   - a reply to a subagent's cross-session message lands in the PARENT
#     session's conversation, never in the subagent
#   - cross-session SendMessage/ListAgents work on Bedrock, Vertex and Foundry
#     and with telemetry disabled
#
# The roster is derived by grep, not hardcoded, so a skill that starts using
# SendMessage tomorrow is covered the day it lands. Frontmatter allowed-tools
# entries count as a mention on purpose: granting the tool without the rule is
# exactly the gap.
#
# Overridable for differential testing:
#   SKILLS_DIR=<dir> bash tests/skills/test-skill-sendmessage-reply-note.sh

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
SKILLS_DIR="${SKILLS_DIR:-$REPO_ROOT/src/skills}"

RED='\033[0;31m'
GREEN='\033[0;32m'
NC='\033[0m'

PASS_COUNT=0
FAIL_COUNT=0
CHECKED=0

echo "=== Skill SendMessage reply-note test (#3772, #3773) ==="
echo "Skills dir: $SKILLS_DIR"
echo ""

for skill_file in "$SKILLS_DIR"/*/SKILL.md; do
  grep -q "SendMessage" "$skill_file" || continue
  CHECKED=$((CHECKED + 1))
  name=$(basename "$(dirname "$skill_file")")
  failed=0
  if ! grep -q "Cross-session replies land in the parent (CC 2.1.248)" "$skill_file"; then
    printf "${RED}FAIL${NC}: %s mentions SendMessage but never states that a subagent's cross-session reply lands in the parent session (#3772)\n" "$name"
    failed=1
  fi
  if ! grep -q "Bedrock, Vertex and Foundry and with telemetry disabled" "$skill_file"; then
    printf "${RED}FAIL${NC}: %s mentions SendMessage but never states cross-session messaging works on Bedrock/Vertex/Foundry and with telemetry off (#3773)\n" "$name"
    failed=1
  fi
  if [ "$failed" -eq 0 ]; then
    PASS_COUNT=$((PASS_COUNT + 1))
    printf "${GREEN}PASS${NC}: %s states both CC 2.1.248 delivery facts\n" "$name"
  else
    FAIL_COUNT=$((FAIL_COUNT + 1))
  fi
done

echo ""
echo "Skills checked: $CHECKED  Passed: $PASS_COUNT  Failed: $FAIL_COUNT"
if [ "$CHECKED" -eq 0 ]; then
  echo -e "${RED}No skill mentions SendMessage; the roster grep is broken, not the skills${NC}"
  exit 1
fi
if [ "$FAIL_COUNT" -gt 0 ]; then
  echo -e "${RED}Skill SendMessage reply-note test FAILED${NC}"
  exit 1
fi
echo -e "${GREEN}Skill SendMessage reply-note test PASSED${NC}"
